module alu (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    input wire [3:0] opcode,
    output reg [31:0] result,
    output reg zero,
    output reg overflow,
    output reg negative
);

    // Internal signals for combinational logic results
    reg [31:0] temp_result;
    reg temp_overflow;
    reg temp_zero;
    reg temp_negative;

    // Combinational logic block to compute the next state of outputs
    // based on current inputs and opcode.
    always @(*) begin
        // Default values for unimplemented opcodes or to ensure all paths assign a value
        temp_result   = 32'b0;
        temp_overflow = 1'b0;

        case (opcode)
            4'b0000: begin // ADD: A + B
                temp_result = a + b;
                // Overflow detection for signed addition (two's complement)
                // Overflow occurs if:
                // 1. (A > 0 and B > 0 and Result < 0) OR
                // 2. (A < 0 and B < 0 and Result > 0)
                temp_overflow = (a[31] & b[31] & ~temp_result[31]) |    // Case 2
                                (~a[31] & ~b[31] & temp_result[31]);    // Case 1
            end

            4'b0001: begin // SUB: A - B
                temp_result = a - b;
                // Overflow detection for signed subtraction (two's complement)
                // Overflow occurs if:
                // 1. (A > 0 and B < 0 and Result < 0) OR
                // 2. (A < 0 and B > 0 and Result > 0)
                // Note: ~b[31] represents the sign of -B.
                temp_overflow = (a[31] & ~b[31] & ~temp_result[31]) |   // Case 2
                                (~a[31] & b[31] & temp_result[31]);     // Case 1
            end

            4'b0010: begin // AND: A & B
                temp_result = a & b;
            end

            4'b0011: begin // OR: A | B
                temp_result = a | b;
            end

            4'b0100: begin // XOR: A ^ B
                temp_result = a ^ b;
            end

            4'b0101: begin // SLL: Logical Left Shift (A << B[4:0])
                // Shift amount is the low 5 bits of B (0 to 31)
                temp_result = a << b[4:0];
            end

            4'b0110: begin // SRL: Logical Right Shift (A >> B[4:0]), zero-filled
                // Shift amount is the low 5 bits of B (0 to 31)
                temp_result = a >> b[4:0];
            end

            4'b0111: begin // SRA: Arithmetic Right Shift (A >>> B[4:0]), sign-extended
                // Shift amount is the low 5 bits of B (0 to 31)
                temp_result = a >>> b[4:0];
            end

            4'b1000: begin // SLT: Set Less Than (Signed)
                // Result is 1 if A < B (signed), else 0
                temp_result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            end

            4'b1001: begin // SLTU: Set Less Than (Unsigned)
                // Result is 1 if A < B (unsigned), else 0
                temp_result = (a < b) ? 32'd1 : 32'd0;
            end

            default: begin // Default case for unsupported opcodes
                temp_result = 32'b0;
                temp_overflow = 1'b0;
            end
        endcase

        // Calculate zero and negative flags based on temp_result
        temp_zero = (temp_result == 32'b0);
        temp_negative = temp_result[31];
    end

    // Sequential logic block to register the outputs
    // All outputs are registered and reset synchronously.
    always @(posedge clk) begin
        if (rst) begin
            result   <= 32'b0;
            zero     <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result   <= temp_result;
            zero     <= temp_zero;
            overflow <= temp_overflow;
            negative <= temp_negative;
        end
    end

endmodule